{
  "name": "recorded-test",
  "version": "1.0.0",
  "private": true,
  "description": "Playwright tests for Recorded Test",
  "scripts": {
    "test": "npx playwright test",
    "test:headed": "npx playwright test --headed",
    "test:ui": "npx playwright test --ui",
    "report": "npx playwright show-report"
  },
  "devDependencies": {
    "@playwright/test": "^1.52.0"
  }
}

import { defineConfig, devices } from '@playwright/test';

/**
 * Playwright configuration for Recorded Test.
 * Generated by CmdRunner from the Execution IR.
 */
export default defineConfig({
  testDir: './tests',
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 2 : 0,
  workers: process.env.CI ? 1 : undefined,
  reporter: 'html',
  use: {
    baseURL: 'http://127.0.0.1:8242',
    viewport: { width: 780, height: 437 },
    trace: 'on-first-retry',
  },
  projects: [
    {
      name: 'chromium',
      use: { ...devices['Desktop Chrome'] },
    },
  ],
});

import { test, expect } from '@playwright/test';

test.describe('Recorded Test', () => {
  test('should complete recorded Test successfully', async ({ page }) => {
    // Fill "New" in the City (type + select)
    await page.locator('#city-a').fill('New')
    await expect.soft(page.locator('#city-a')).toHaveValue('New')

    // Click the New York
    await page.locator('[class~="opt"]').click()

    // Fill "App" in the Fruit (type + Enter)
    await page.locator('#fruit-b').fill('App')
    await expect.soft(page.locator('#fruit-b')).toHaveValue('App')

    // Fill "query" in the Search (type + click elsewhere)
    await page.locator('#search-c').fill('query')
    await expect.soft(page.locator('#search-c')).toHaveValue('query')

    // Click the Save
    await page.locator('#save-btn').click()

    // Open the Status (readonly combobox) list
    await page.locator('#status-d').click()

    // Select Active
    await page.locator('[class~="opt"]').click()

    // Fill "Chro" in the Browser (native datalist)
    await page.locator('#browser-e').fill('Chro')
    await expect.soft(page.locator('#browser-e')).toHaveValue('Chro')

    // Click the Save
    await page.locator('#save-btn').click()
  });
});
